    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private AlarmEditorActivity activity;
    private String step="fixture admission";
    private void await(java.util.function.BooleanSupplier ready){assertTrue(step,device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return ready.getAsBoolean();}},5000));}
    private View find(View root,String value,boolean description){if(description?value.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()):root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),value,description);if(view!=null)return view;}return null;}
    private View focusedWindow(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0){assertNull("One focused application window",found);found=root;}return found;}
    private void ready(){await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()&&focusedWindow()==activity.getWindow().getDecorView());return yes[0];});}
    private void frame(View owner)throws Exception{CountDownLatch drawn=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Exact focused window before frame",owner,focusedWindow());owner.getViewTreeObserver().registerFrameCommitCallback(drawn::countDown);owner.invalidate();});assertTrue(step+": rendered owned frame",drawn.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame("Frame retains its exact focused window",owner,focusedWindow()));}
    private void require(String value,boolean description){step="require page "+value;ready();await(()->{boolean[] yes={false};i.runOnMainSync(()->{View target=find(activity.getWindow().getDecorView(),value,description);if(target==null)return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();yes[0]=target.isShown()&&target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return yes[0];});}
    private boolean hasText(String text){boolean[] found={false};i.runOnMainSync(()->found[0]=find(activity.getWindow().getDecorView(),text,false)!=null);return found[0];}
    private void input(View owner,String value,boolean description)throws Exception{
        step="single owned input "+value;
        await(()->{boolean[] ready={false};i.runOnMainSync(()->{if(focusedWindow()!=owner)return;View target=find(owner,value,description);if(target==null)return;while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();if(!target.isClickable()||!target.isEnabled())return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();ready[0]=target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return ready[0];});
        frame(owner);Rect screen=new Rect();i.runOnMainSync(()->{assertSame(owner,focusedWindow());View target=find(owner,value,description);assertNotNull(step,target);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertSame("Control belongs to exact decor",owner,target.getRootView());assertTrue(target.isClickable()&&target.isEnabled());Rect visible=new Rect();assertTrue(target.getGlobalVisibleRect(visible));assertEquals("Complete control width",target.getWidth(),visible.width());assertEquals("Complete control height",target.getHeight(),visible.height());assertTrue("48dp width",visible.width()>=Design.dp(c,48));assertTrue("48dp height",visible.height()>=Design.dp(c,48));int[] position=new int[2];target.getLocationOnScreen(position);screen.set(position[0],position[1],position[0]+target.getWidth(),position[1]+target.getHeight());});
        // Exactly one input. Never repeat a delivered action after an absent postcondition.
        assertTrue(step+": dispatched once",device.click(screen.centerX(),screen.centerY()));
    }
    private void click(String text)throws Exception{ready();input(activity.getWindow().getDecorView(),text,false);}
    private void clickDescription(String value)throws Exception{ready();input(activity.getWindow().getDecorView(),value,true);}
    private View choiceDialog(String title)throws Exception{step="await owned "+title+" dialog";View[] owner={null};await(()->{i.runOnMainSync(()->{View root=focusedWindow();if(root!=null&&root!=activity.getWindow().getDecorView()&&find(root,(title.equals("Reset backup sound")?"Actions for ":"Options for ")+title,true)!=null)owner[0]=root;});return owner[0]!=null;});frame(owner[0]);return owner[0];}
    private View durationDialog()throws Exception{return choiceDialog("Snooze duration");}
    private void choice(String title,String value)throws Exception{clickDescription(title);choose(choiceDialog(title),value,true);}
    private void assertMainAboveSave()throws Exception{step="whole reference rows above Save";ready();frame(activity.getWindow().getDecorView());i.runOnMainSync(()->{View root=activity.getWindow().getDecorView(),save=find(root,"Use snooze settings",false);assertNotNull(save);Rect footer=new Rect();assertTrue(save.getGlobalVisibleRect(footer));for(String label:new String[]{"Snooze duration","Maximum snoozes","Shorten each snooze","Backup alarm","Escalate after","Backup sound","Backup volume","Wake-up check"}){View row=find(root,label,true);assertNotNull(label,row);if(row instanceof android.widget.Switch)row=(View)row.getParent();Rect visible=new Rect();assertTrue(label+" initially visible",row.getGlobalVisibleRect(visible));assertEquals(label+" whole width",row.getWidth(),visible.width());assertEquals(label+" whole height",row.getHeight(),visible.height());assertTrue(label+" above Save",visible.bottom<=footer.top);}assertTrue("Actual backup volume control",find(root,"Backup volume",true) instanceof android.widget.SeekBar);
            android.widget.SeekBar bar=(android.widget.SeekBar)find(root,"Backup volume",true);android.graphics.drawable.LayerDrawable track=(android.graphics.drawable.LayerDrawable)bar.getProgressDrawable();android.graphics.drawable.Drawable progress=track.findDrawableByLayerId(android.R.id.progress);assertNotNull("Independent secondary level target",track.findDrawableByLayerId(android.R.id.secondaryProgress));int level=(int)((bar.getProgress()-bar.getMin())/(float)(bar.getMax()-bar.getMin())*10000);assertEquals("Native primary level survives secondary refresh",level,progress.getLevel());Rect bounds=track.getBounds();assertEquals("Full-width progress layer, not intrinsic1px",bounds,progress.getBounds());assertTrue(bounds.width()>1&&bounds.height()>0);
            android.graphics.Bitmap rendered=android.graphics.Bitmap.createBitmap(bounds.width(),bounds.height(),android.graphics.Bitmap.Config.ARGB_8888);try{android.graphics.Canvas canvas=new android.graphics.Canvas(rendered);canvas.translate(-bounds.left,-bounds.top);track.draw(canvas);int edge=bounds.width()*level/10000;if(edge>4)assertEquals("Native drawable renders the active rail",Design.BROWN,rendered.getPixel(edge/2,bounds.height()/2));if(edge+4<bounds.width())assertEquals("Native drawable retains the inactive rail",0xffe6d4c5,rendered.getPixel((edge+bounds.width())/2,bounds.height()/2));}finally{rendered.recycle();}});}
    private void choose(View owner,String value,boolean description)throws Exception{input(owner,value,description);step="await exact selector detachment after "+value;await(()->!owner.isAttachedToWindow());ready();frame(activity.getWindow().getDecorView());}
    private void launch(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("route","snooze").putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Snooze & backup",false);}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Snooze & backup",false);}
    private void capture(String name)throws Exception{step="capture advanced-snooze-"+name;ready();frame(activity.getWindow().getDecorView());File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"advanced-snooze-"+name+".png")));}
    private void captureDialog(String name,View owner)throws Exception{step="capture advanced-snooze-"+name;frame(owner);File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"advanced-snooze-"+name+".png")));}
    private View recreatePicker(String title)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}return choiceDialog(title);}
    private Alarm draft()throws Exception{Bundle state=new Bundle();i.runOnMainSync(()->activity.onSaveInstanceState(state));return Alarm.read(new JSONObject(state.getString("draft")));}
    private void volume(int percent)throws Exception{require("Backup volume",true);frame(activity.getWindow().getDecorView());i.runOnMainSync(()->{android.widget.SeekBar seek=(android.widget.SeekBar)find(activity.getWindow().getDecorView(),"Backup volume",true);assertEquals(10,seek.getMin());assertEquals(100,seek.getMax());Bundle arguments=new Bundle();arguments.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,percent);assertTrue("One actual native accessible slider action",seek.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),arguments));assertEquals(percent,seek.getProgress());});require(percent+"%",false);assertEquals(percent,draft().backupSound.volume);}
    private static final class FakeOutputs implements AlarmPlayback.Sink,AlarmVolumeLease.Port,AlarmVolumeLease.Journal {
        final List<Layer> layers=new ArrayList<>();final AlarmVolumeLease lease=new AlarmVolumeLease(this,this,"private-run","private-owner");AlarmVolumeLease.State state;int level=8,writes,stops,reviews,failures;boolean deny,fixed,unwritable,boost;float scale;long elapsed=180000;
        final class Layer implements AlarmPlayback.Layer {final String tone;AlarmPlayback.Ready ready;boolean closed;float gain=-1;int starts;Layer(String tone){this.tone=tone;}public void prepare(AlarmPlayback.Ready value){ready=value;}public void gain(float value){assertFalse(closed);gain=value;}public void start(AlarmPlayback.Ready activated){assertFalse(closed);assertTrue(gain>=0);starts++;activated.ready();}public void close(){closed=true;}}
        public AlarmPlayback.Layer create(String tone){Layer layer=new Layer(tone);layers.add(layer);return layer;}public void volume(AlarmPlayback.Layer layer,AlarmWakePolicy policy,boolean backup){boost=policy.boost(backup);scale=lease.acquire(policy,backup);}public void stopped(){lease.release();stops++;}public void backupReview(){reviews++;}public void failed(){failures++;}
        public int read(){return level;}public int maximum(){return 20;}public void write(int value){writes++;if(deny)throw new SecurityException("Fake volume denial");if(!fixed)level=value;}public AlarmVolumeLease.State load(){return state;}public boolean save(AlarmVolumeLease.State value){if(unwritable)return false;state=value;return true;}public void clear(String owner){if(state!=null&&state.owner.equals(owner))state=null;}
        AlarmPlayback engine(Alarm alarm){return new AlarmPlayback(alarm,this,()->elapsed,()->elapsed);}Layer latest(){return layers.get(layers.size()-1);}void prepared(){latest().ready.ready();}
    }
    private void fakePlayback(Alarm saved)throws Exception{
        step="real Playback/WakePolicy/Lease with fake outputs";assertTrue(AlarmAudioSink.captureQuiet());assertFalse(AlarmService.active);
        Alarm alarm=Alarm.read(saved.json());alarm.volume=40;alarm.extraLoud=true;alarm.rampSeconds=120;alarm.soundDelaySeconds=60;
        FakeOutputs output=new FakeOutputs();AlarmPlayback player=output.engine(alarm);player.start();output.prepared();assertEquals(alarm.tone,output.latest().tone);assertEquals(20,output.level);assertTrue(output.boost);FakeOutputs.Layer primary=output.latest();
        player.backup(true);assertEquals("Lower level applies while replacement prepares",7,output.level);assertFalse(output.boost);assertFalse(primary.closed);assertEquals("chime",output.latest().tone);output.prepared();assertTrue(primary.closed);assertEquals(1,output.latest().gain,0);assertEquals(1,output.latest().starts);
        player.backup(false);assertEquals(20,output.level);assertTrue(output.boost);assertEquals(alarm.tone,output.latest().tone);output.prepared();player.backup(true);output.latest().ready.failed();assertFalse("Failed replacement retains working primary",output.layers.get(2).closed);assertEquals(7,output.level);assertFalse(output.boost);player.stop();assertEquals(8,output.level);assertNull(output.state);assertEquals(1,output.stops);
        FakeOutputs restart=new FakeOutputs();restart.elapsed=0;AlarmPlayback restarted=restart.engine(alarm);restarted.start(true);restart.prepared();assertEquals("chime",restart.latest().tone);assertEquals(1,restart.latest().gain,0);assertEquals(1,restart.latest().starts);assertEquals(7,restart.level);assertFalse(restart.boost);restarted.backup(false);FakeOutputs.Layer late=restart.latest();restarted.stop();late.ready.ready();assertEquals(0,late.starts);assertTrue(late.closed);assertEquals(8,restart.level);
        FakeOutputs fallback=new FakeOutputs();fallback.elapsed=0;AlarmPlayback fail=fallback.engine(alarm);fail.start(true);fallback.latest().ready.failed();assertEquals("daybreak",fallback.latest().tone);fallback.prepared();assertEquals(7,fallback.level);assertFalse(fallback.boost);fail.stop();assertEquals(8,fallback.level);
        AlarmWakePolicy policy=new AlarmWakePolicy(alarm);for(int mode=0;mode<3;mode++){FakeOutputs constrained=new FakeOutputs();constrained.deny=mode==0;constrained.unwritable=mode==1;constrained.fixed=mode==2;float scale=constrained.lease.acquire(policy,true);assertEquals(mode==2?7/8f:.35f,scale,.0001f);assertEquals(8,constrained.level);constrained.deny=false;constrained.lease.release();assertEquals(8,constrained.level);}
        FakeOutputs changed=new FakeOutputs();AlarmPlayback user=changed.engine(alarm);user.start(true);changed.prepared();changed.level=4;user.backup(false);assertEquals("User stream change is retained when leaving backup",4,changed.level);changed.prepared();user.stop();assertEquals(4,changed.level);
        Alarm quiet=Alarm.read(alarm.json());quiet.id=-1;FakeOutputs quietOutput=new FakeOutputs();AlarmPlayback quietPlayer=quietOutput.engine(quiet);quietPlayer.start(true);quietOutput.prepared();quietPlayer.backup(true);assertEquals(1,quietOutput.layers.size());assertEquals(0,quietOutput.writes);assertEquals(.25,quietOutput.scale,0);assertFalse(quietOutput.boost);quietPlayer.stop();assertEquals(8,quietOutput.level);
        Alarm legacy=Alarm.read(saved.json());legacy.setBackupSound(AlarmBackupSound.DEFAULT);assertFalse(legacy.json().has("backupSound"));FakeOutputs old=new FakeOutputs();AlarmPlayback oldPlayer=old.engine(legacy);oldPlayer.start(true);old.prepared();assertEquals("pulse",old.latest().tone);assertEquals(20,old.level);oldPlayer.stop();assertEquals(8,old.level);
        Alarm invalid=Alarm.read(alarm.json().put("backupSound",new JSONObject().put("tone","missing").put("volume",35)));FakeOutputs bad=new FakeOutputs();AlarmPlayback unchanged=bad.engine(invalid);unchanged.start();bad.prepared();assertEquals(alarm.tone,bad.latest().tone);assertEquals(1,bad.reviews);unchanged.backup(true);bad.prepared();assertEquals("pulse",bad.latest().tone);assertEquals(20,bad.level);unchanged.stop();assertTrue(invalid.backupSoundInvalid);assertEquals("missing",invalid.json().getJSONObject("backupSound").getString("tone"));assertTrue(AlarmAudioSink.captureQuiet());assertFalse(AlarmService.active);
    }
    private void portableAndDefaults(AlarmSkipFixture fixture,Alarm saved)throws Exception{
        step="legacy13/new14/defaults/malformed preservation";
        Alarm legacy=Alarm.read(saved.json());legacy.setBackupSound(AlarmBackupSound.DEFAULT);String legacyJson=legacy.json().toString();assertFalse(legacy.json().has("backupSound"));assertEquals(legacyJson,Alarm.read(legacy.json()).json().toString());AlarmDefaults defaults=AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(saved)));Alarm fresh=defaults.create(9);assertEquals(saved.backupSound,fresh.backupSound);assertFalse(fresh.enabled);assertTrue(fresh.days.isEmpty());assertEquals(7,fresh.hour);
        Alarm partial=Alarm.read(saved.json());ContentValues label=new ContentValues();label.put("label","Private partial update");AlarmContentContract.patch(partial,AlarmContentContract.fields(label,false));assertEquals(saved.backupSound,Alarm.read(partial.json()).backupSound);assertEquals(AlarmSkips.scheduleKey(saved),AlarmSkips.scheduleKey(partial));assertFalse(Arrays.asList(AlarmContentContract.COLUMNS).contains("backupSound"));
        String database=fixture.database+"-portable";try(Store source=fixture.open();Store target=new Store(c,database)){JSONObject portable=source.backup();assertEquals(14,portable.getInt("format"));Backup.validate(portable);Backup.restoreData(target,portable);Alarm restored=target.alarm(saved.id);assertEquals(saved.backupSound,restored.backupSound);assertEquals(saved.json().toString(),restored.json().toString());JSONObject older=new JSONObject(portable.toString()).put("format",13);for(int n=0;n<older.getJSONArray("alarms").length();n++)older.getJSONArray("alarms").getJSONObject(n).remove("backupSound");Backup.restoreData(target,older);assertEquals(AlarmBackupSound.DEFAULT,target.alarm(saved.id).backupSound);Backup.restoreData(target,portable);String fingerprint=BackupFingerprint.read(target);
            JSONObject valid=saved.backupSound.json();for(Object raw:new Object[]{JSONObject.NULL,"pulse",new JSONObject(),new JSONObject(valid.toString()).put("tone","system"),new JSONObject(valid.toString()).put("tone","content://forbidden"),new JSONObject(valid.toString()).put("volume",35.5),new JSONObject(valid.toString()).put("volume","35"),new JSONObject(valid.toString()).put("volume",9),new JSONObject(valid.toString()).put("volume",101),new JSONObject(valid.toString()).put("extra",true)}){Alarm broken=Alarm.read(saved.json().put("backupSound",raw));assertTrue(broken.backupSoundInvalid);assertEquals(String.valueOf(raw),String.valueOf(broken.json().get("backupSound")));assertEquals(saved.tone,broken.tone);assertEquals(saved.volume,broken.volume);assertEquals(AlarmSkips.scheduleKey(saved),AlarmSkips.scheduleKey(broken));assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(broken));JSONObject rejected=new JSONObject(portable.toString());rejected.getJSONArray("alarms").put(0,broken.json());assertThrows(JSONException.class,()->Backup.restoreData(target,rejected));assertEquals(fingerprint,BackupFingerprint.read(target));}
        }finally{c.deleteDatabase(database);}
    }
    private boolean failureCaptured;
    private void failure(Throwable problem){if(failureCaptured)return;failureCaptured=true;try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());try(PrintWriter out=new PrintWriter(new File(folder,"advanced-snooze-failure.txt"),"UTF-8")){out.println(step);problem.printStackTrace(out);}device.takeScreenshot(new File(folder,"advanced-snooze-failure.png"));device.dumpWindowHierarchy(new File(folder,"advanced-snooze-failure.xml"));}catch(Exception diagnostic){problem.addSuppressed(diagnostic);}}
    @Test public void longMaximumAndPerPressChoicePersistCancelAndRecreateWithoutRuntime()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertEquals(0,Prefs.number(c,"checkPending",0));List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks observer=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue(a instanceof AlarmEditorActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(observer);
        try(AlarmSkipFixture f=new AlarmSkipFixture()){try{
            Alarm initial=f.load();initial.enabled=false;initial.awakeCheck=1;initial.backupMinutes=5;initial.shortenSnoozes=false;initial.snoozeTotalMinutes=90;initial.timing=new AlarmTiming(60,2,3,30);try(Store store=f.open()){store.save(initial);}String original=f.load().json().toString();
            launch(initial);assertMainAboveSave();capture("initial");
            clickDescription("Snooze options");require("Snooze options",false);capture("options");clickDescription("Choose duration each time");recreate();require("Snooze options",false);capture("options-recreated");click("Done");require("Snooze settings",false);
            clickDescription("Snooze duration");View duration=durationDialog();choose(duration,"60 min",true);require("Up to 60 min",false);
            clickDescription("Snooze duration");View cancel=durationDialog();choose(cancel,"Cancel",false);require("Up to 60 min",false);assertEquals(5,f.load().snoozeMinutes);assertFalse(f.load().inputs.chooseSnooze);
            clickDescription("Backup sound");View tone=choiceDialog("Backup sound");captureDialog("sound-picker",tone);tone=recreatePicker("Backup sound");captureDialog("sound-picker-recreated",tone);choose(tone,"Cancel",false);assertEquals(AlarmBackupSound.DEFAULT,draft().backupSound);choice("Backup sound","Chime");volume(35);assertEquals(new AlarmBackupSound("chime",35),draft().backupSound);
            choice("Maximum snoozes","2");clickDescription("Shorten each snooze");choice("Escalate after","7 min");choice("Wake-up check","After 10 min");assertMainAboveSave();capture("draft");
            recreate();require("Up to 60 min",false);assertMainAboveSave();capture("recreated");assertEquals("Navigation and choices only change the draft",original,f.load().json().toString());assertEquals(0,f.schedules);click("Use snooze settings");require("Edit alarm",false);click("Save alarm");await(activity::isDestroyed);
            Alarm saved=f.load();assertEquals(60,saved.snoozeMinutes);assertTrue(saved.inputs.chooseSnooze);assertEquals(2,saved.snoozeLimit);assertTrue(saved.shortenSnoozes);assertEquals(7,saved.backupMinutes);assertEquals(10,saved.awakeCheck);assertEquals(90,saved.snoozeTotalMinutes);assertEquals(initial.timing,saved.timing);assertEquals(new AlarmBackupSound("chime",35),saved.backupSound);assertEquals(1,f.schedules);Alarm expected=Alarm.read(initial.json());expected.snoozeMinutes=60;expected.inputs=expected.inputs.chooseSnooze(true);expected.snoozeLimit=2;expected.shortenSnoozes=true;expected.backupMinutes=7;expected.awakeCheck=10;expected.setBackupSound(saved.backupSound);assertEquals("Every original user field retained",expected.json().toString(),saved.json().toString());
            launch(saved);require("Up to 60 min",false);require("Chime",false);require("35%",false);assertMainAboveSave();capture("reopened");
            portableAndDefaults(f,saved);fakePlayback(saved);i.runOnMainSync(activity::finish);await(activity::isDestroyed);
            JSONObject raw=new JSONObject().put("tone","unreadable").put("volume",35);Alarm invalid=Alarm.read(saved.json().put("backupSound",raw));launch(invalid);require("Needs review",false);capture("invalid");click("Use snooze settings");require("Edit alarm",false);click("Save alarm");require("Review backup sound settings in Snooze before saving.",false);assertEquals(saved.json().toString(),f.load().json().toString());assertTrue(draft().backupSoundInvalid);assertEquals(raw.toString(),draft().json().getJSONObject("backupSound").toString());i.runOnMainSync(activity::finish);await(activity::isDestroyed);
            launch(invalid);clickDescription("Reset backup sound");choose(choiceDialog("Reset backup sound"),"Cancel",false);assertEquals(raw.toString(),draft().json().getJSONObject("backupSound").toString());recreate();assertTrue(draft().backupSoundInvalid);choice("Reset backup sound","Use Pulse at 100%");require("Pulse",false);require("100%",false);assertFalse(draft().backupSoundInvalid);assertFalse(draft().json().has("backupSound"));capture("repaired-draft");assertEquals("Repair remains a draft until Save alarm",saved.json().toString(),f.load().json().toString());assertEquals(1,f.schedules);
        }catch(Exception|AssertionError problem){failure(problem);throw problem;}finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});await(()->owned.stream().allMatch(Activity::isDestroyed));}}catch(Exception|AssertionError problem){failure(problem);throw problem;}finally{app.unregisterActivityLifecycleCallbacks(observer);}
    }
